void dvC821_OPDMutexLockEvent(UINT16 uiEvent, const char *pcFunc)  //A35G2_Simon_0112
{
    uOPD_DATA uOPDData ;

    snprintf(uOPDData.cString, 128,  "%s,%s", pcFunc, cLastTakeC821Semaphore);

    utilOPD_EventSet(uiEvent, &uOPDData);
}

BOOL dvC821_SemaphoreTake(BOOL cEnable, const char *pcSemaphore)
{
    BOOL bResult = FALSE;

    if(cEnable)
    {
        bResult = Board_SSP_SemaphoreTake(eBOARD_SSP_CS_C821);

        if(bResult == FALSE)
        {
            dvC821_OPDMutexLockEvent(eOPD_MUTEX_LOCKED_LOG, pcSemaphore);   //A35G2_Simon_0112
            LOG_MSG(db_DV_SEMAPHORE, "(func:%s) is Fail, last take semaphore func %s\r\n", pcSemaphore, cLastTakeC821Semaphore);
        }
        else
        {
            sprintf(cLastTakeC821Semaphore, "%s", pcSemaphore);
        }
    }
    else
    {
        bResult = Board_SSP_SemaphoreGive(eBOARD_SSP_CS_C821);

        sprintf(cLastTakeC821Semaphore, "\0");
    }

    return bResult;
}

void dvC821_UpgradeAccess_Set(BOOL bEnable)	//A65_OPTOMA_Doulas_0126
{
    bUpgradeEnable = bEnable;
}

BOOL dvC821_UpgradeAccess_Get(void)			//A65_OPTOMA_Doulas_0126
{
    return bUpgradeEnable;
}

static void dvC821_ResetTimeInState(void)
{
    m_ulStartTicks = xTaskGetTickCount();
}

static UINT32 dvC821_TimeElapsedInState(void)
{
    TickType_t ulTicks;

    ulTicks = xTaskGetTickCount();

    if(m_ulStartTicks > ulTicks)
    {
        return (0xFFFFFFFF - m_ulStartTicks + 1 + ulTicks) / portTICK_RATE_MS;
    }
    else
    {
        return (ulTicks - m_ulStartTicks) / portTICK_RATE_MS;
    }
}

void dvC821_Buffer_Flush(void)
{
    ASSERT(uiWriteIdx <= SPI_BUFFER_SIZE); //A35G2_CDS_Larry_0030

    if(uiWriteIdx)
    {
        SPI_SendWriteCmd(eBOARD_SSP_CS_C821, aucWriteBuffer, uiWriteIdx, 1);
        uiWriteIdx = 0;
    }
}

void dvC821_WriteToBuffer(const UINT32 ulAddr, UINT32 ulData, const UINT8 ucBankOffset)
{
    UINT8 ucBank, ucReg, ucSize;
    //-------------------------------------------------------------
    ucBank = (ulAddr >> 16) & 0x3F;
    ucReg = (ulAddr >> 8) & 0xFF;
    ucSize = ulAddr & 0xFF;

    ucBank += ucBankOffset;

    m_ucCurrentBank = dvC821_CurrentBankGet();

    //-------------------------------------------------------------
    if(ucReg == 0x00)
    {
        m_ucCurrentBank = ulData & 0x3F;
        dvC821_CurrentBankSet(m_ucCurrentBank);
    }
    else if((ucBank != m_ucCurrentBank) && (ucReg >= 0x08))//Change to appropriate bank
    {
        m_ucCurrentBank = ucBank;
        dvC821_CurrentBankSet(m_ucCurrentBank);

        aucWriteBuffer[uiWriteIdx++] = 0x80;
        aucWriteBuffer[uiWriteIdx++] = ucBank;

        ASSERT(uiWriteIdx <= SPI_BUFFER_SIZE); //A35G2_CDS_Larry_0030

        dvC821_Buffer_Flush();
    }

    //-------------------------------------------------------------
    while(ucSize > 0)
    {
        aucWriteBuffer[uiWriteIdx++] = ucReg | 0x80;
        aucWriteBuffer[uiWriteIdx++] = (UINT8)(ulData & 0xFF);

        if(uiWriteIdx >= SPI_BUFFER_SIZE)
        {
            dvC821_Buffer_Flush();
        }

        ucReg++;
        ulData >>= 0x08;
        ucSize--;
    }
}

void dvC821_Write(const UINT32 ulAddr, UINT32 ulData, const UINT8 ucBankOffset)
{
    UINT8 ucBank, ucReg, ucSize, ucIdx;
    UINT8 ucWBuffer[16];
    //-------------------------------------------------------------
    ucBank = (ulAddr >> 16) & 0x3F;
    ucReg = (ulAddr >> 8) & 0xFF;
    ucSize = ulAddr & 0xFF;

    ucBank += ucBankOffset;

    dvC821_Buffer_Flush(); //A35G2_CDS_Larry_0030

    m_ucCurrentBank = dvC821_CurrentBankGet();

    //-------------------------------------------------------------
    if(ucReg == 0x00)
    {
        m_ucCurrentBank = ulData & 0x3F;
        dvC821_CurrentBankSet(m_ucCurrentBank);
    }
    else if((ucBank != m_ucCurrentBank) && (ucReg >= 0x08))//Change to appropriate bank
    {
        m_ucCurrentBank = ucBank;
        dvC821_CurrentBankSet(m_ucCurrentBank);

        ucWBuffer[0] = 0x80;
        ucWBuffer[1] = ucBank;

        SPI_SendWriteCmd(eBOARD_SSP_CS_C821, ucWBuffer, 2, 1);
    }

    //-------------------------------------------------------------
    ucIdx = 0;
    while(ucSize > 0)
    {
        ucWBuffer[ucIdx++] = ucReg | 0x80;
        ucWBuffer[ucIdx++] = (UINT8)(ulData & 0xFF);

        ucReg++;
        ulData >>= 0x08;
        ucSize--;
    }

    SPI_SendWriteCmd(eBOARD_SSP_CS_C821, ucWBuffer, ucIdx, 1);

    return;
}

void dvC821_BurstRead_FixedAdd(const UINT32 ulAddr, UINT16 uiSize, UINT8 *pucData) //A70LV_Larry_0139
{
    UINT8 ucBank, ucReg, ucWBuffer[2];
    UINT8 *pcBuffer = malloc(uiSize + 4);

    m_ucCurrentBank = dvC821_CurrentBankGet();

    dvC821_Buffer_Flush();

    if(pcBuffer == NULL)
    {
        LOG_MSG(db_ALWAYS,"\n%s(%d) malloc fail\n", __FUNCTION__ , __LINE__);
        return;
    }

    //-------------------------------------------------------------
    ucBank = (ulAddr >> 16) & 0x3F;
    ucReg = (ulAddr >> 8) & 0xFF;

    ucBank = BURST_MODE_FIXED_ADDRESS | ucBank;
    //b7-b6
    //0 Normal mode
    //1 Serial burst mode: address fixed
    //2 Serial burst mode: address auto increment
    //3 T.B.D
    //-------------------------------------------------------------
    if(ucReg == 0x00)
    {
        m_ucCurrentBank = *pucData & 0x3F;
        m_ucCurrentBank = BURST_MODE_FIXED_ADDRESS | m_ucCurrentBank;
        dvC821_CurrentBankSet(m_ucCurrentBank);
    }
    else if((ucBank != m_ucCurrentBank) && (ucReg >= 0x08))//Change to appropriate bank
    {
        m_ucCurrentBank = ucBank;
        dvC821_CurrentBankSet(m_ucCurrentBank);

        ucWBuffer[0] = 0x80;
        ucWBuffer[1] = ucBank;

        SPI_SendWriteCmd(eBOARD_SSP_CS_C821, ucWBuffer, 2, 1);
    }

    //-------------------------------------------------------------
    ucWBuffer[0] = ucReg;

    SPI_SendReadCmd(eBOARD_SSP_CS_C821, ucWBuffer, pcBuffer, 2, (uiSize+1));

    memcpy(pucData, &pcBuffer[1], uiSize); //0 is dummy
    free(pcBuffer);
}

