static void dvC821_Init_Output_CSC1(const eMCT eCH)
{
    UINT8 ucRegOffset = 0;

    if(eCH >= eMCT_LAST)
    {
        return;
    }

    ucRegOffset = (eCH == eMCT_CH1) ? 0 : 13;

    dvC821_Write(B6_OCSC1CF00CH1,	0x3265, ucRegOffset);	//output color conversion coefficient	// Ref.  OCSC1CF/YUV-RGB_709CH1.txt
    dvC821_Write(B6_OCSC1CF01CH1,	0x2000, ucRegOffset);
    dvC821_Write(B6_OCSC1CF02CH1,	0x0000, ucRegOffset);
    dvC821_Write(B6_OCSC1CF10CH1,	0xf105, ucRegOffset);
    dvC821_Write(B6_OCSC1CF11CH1,	0x2000, ucRegOffset);
    dvC821_Write(B6_OCSC1CF12CH1,	0xfa02, ucRegOffset);
    dvC821_Write(B6_OCSC1CF20CH1,	0x0000, ucRegOffset);
    dvC821_Write(B6_OCSC1CF21CH1,	0x2000, ucRegOffset);
    dvC821_Write(B6_OCSC1CF22CH1,	0x3b61, ucRegOffset);
}

