	val=(INT32)(dYuvRgb2[0][2]*8192+0.5)&0xffff; dvC821_Write(B6_OCSC1CF02CH1,val,ucRegOffset);
	val=(INT32)(dYuvRgb2[1][0]*8192+0.5)&0xffff; dvC821_Write(B6_OCSC1CF10CH1,val,ucRegOffset);
	val=(INT32)(dYuvRgb2[1][1]*8192+0.5)&0xffff; dvC821_Write(B6_OCSC1CF11CH1,val,ucRegOffset);
	val=(INT32)(dYuvRgb2[1][2]*8192+0.5)&0xffff; dvC821_Write(B6_OCSC1CF12CH1,val,ucRegOffset);
	val=(INT32)(dYuvRgb2[2][0]*8192+0.5)&0xffff; dvC821_Write(B6_OCSC1CF20CH1,val,ucRegOffset);
	val=(INT32)(dYuvRgb2[2][1]*8192+0.5)&0xffff; dvC821_Write(B6_OCSC1CF21CH1,val,ucRegOffset);
