    dYuvRgb1[0][2] = dYuvRgb1[0][2] * 8192;
    dYuvRgb1[1][2] = dYuvRgb1[1][2] * 8192;
    dYuvRgb1[2][2] = dYuvRgb1[2][2] * 8192;

