	val=(INT32)(dYuvRgb1[1][1]*8192+0.5)&0xffff; dvC821_Write(B6_OCSC1CF11CH1,val,ucRegOffset);
	val=(INT32)(dYuvRgb1[1][2]*8192+0.5)&0xffff; dvC821_Write(B6_OCSC1CF12CH1,val,ucRegOffset);
