    dvC821_WriteToBuffer(B11_LUTWRCH1, 0xFF, ucRegOffset);

    // EP p2 = 1.0
    dvC821_WriteToBuffer(B11_LUTCFCH1, 0x00004000, ucRegOffset);

    dvC821_WriteToBuffer(B11_LUTWADCH1, 0x20, ucRegOffset);
