static void dvC821_ConfigInput_2K(const eMCT eCH)//dvC821_SetupInput
{
    UINT8 ucRegOffset;

    if(eCH >= eMCT_LAST)
    {
        return;
    }

    ucRegOffset = (eCH == eMCT_CH1) ? 0 : 13;

    m_sChannelInfo[eCH].ucMCT = 0x01;

    //LOG_MSG(db_APP_DATAPATH, "<5>%d\n", m_sChannelInfo[eCH].ucMCT);

    if(eCH == eMCT_CH1)
    {
        dvC821_Write(BN_MCT1, m_sChannelInfo[eCH].ucMCT, 0);    //Enable Image Output
    }
    else if(eCH == eMCT_CH2)
    {
        dvC821_Write(BN_MCT2, m_sChannelInfo[eCH].ucMCT, 0);
    }

  //  dvC821_Write(B1_INTEN, m_sChannelInfo[eCH].ulInterruptEnable, 0); //A70LV_Doulas_0002


    m_sChannelInfo[eCH].ucISYCT = 0x00;
    dvC821_WriteToBuffer(B8_ISYCTCH1, m_sChannelInfo[eCH].ucISYCT, ucRegOffset);
    dvC821_WriteToBuffer(B8_DIFCTCH1, 0x83, ucRegOffset);      //
    dvC821_WriteToBuffer(B8_ICOLORCTCH1, 0x08, ucRegOffset);   //A70LV_Doulas_0080 modify//Enable YUV422 to YUV444 conversion in PIACT area
    //dvC821_Write(B8_AUTOFLDCH1, 0x80, ucRegOffset);    //Field auto recognition enable
    dvC821_WriteToBuffer(B8_AUTOFLDCH1, 0x00, ucRegOffset);    //Field auto recognition enable
    dvC821_WriteToBuffer(B9_SHRNKADJCH1, 0x02, ucRegOffset);   //Shrink compensation enable

    dvC821_WriteToBuffer(B8_ISWPCH1,  	0x00, ucRegOffset);	    //Input Data Swap   //A70LV_Doulas_0002

    dvC821_WriteToBuffer(B8_UVLPCOEF0CH1,	0x00, ucRegOffset); //Input UV low pass filter coefficient	//	YUV444->YUV422 filter
    dvC821_WriteToBuffer(B8_UVLPCOEF1CH1,	0x04, ucRegOffset);
    dvC821_WriteToBuffer(B8_UVLPCOEF2CH1,	0x08, ucRegOffset);

    //		dvC821_Write( B17_PTHCH1, 0x80, ich_ofst );
    //TODO
    dvC821_WriteToBuffer(B8_PTHCH1, 0xF0, ucRegOffset);        //Characteristics measurement threshold
    //dvC821_Write(B8_PTHCH1, 0x04, ucRegOffset);
    dvC821_Buffer_Flush();
}

