static void dvC821_ConfigTTL_2K(const eMCT eCH, const UINT8 ucOFLDSel, const BOOL bEnable)
{
    UINT8 ucData = 0;
 //   eCH = eCH;

    if(bEnable)
    {
        ucData |= 0x40;
        ucData |= (ucOFLDSel & 0x03) ;
        //POOSEL[1:0]: CMOS image output port CH select
        //b1 b0 CMOS image output port CH select
        //POOSEL[1] POOSEL[0] Operation
        // 0 0  CH1 output
        // 0 1  CH2 output
        // 1 0  Bypass output,CH selected with ISEL1[1:0] (address 01h, bit 6-5) is output.
        // 1 1  Output stop
    }

    dvC821_Write(B0_CMOSOUTSETUP, ucData, 0);

}
#endif

static void dvC821_ConfigLVDS_2K(const ePANEL_ID ePanelId)//dvC821_SetupLVDS
{
    if(ePanelId >= ePANEL_ID_LAST)
    {
        return;
    }

	dvC821_WriteToBuffer(B0_LVDSOCLKCT,		0x01,0);	//Output side LVDS clock control
	dvC821_WriteToBuffer(B0_LVDSOSETUP,		0x05,0);//0x07,0);//0x05,0);	//A70LV_Doulas_0045 modify  //A70LV_Doulas_0034 modify  //Output side LVDS setup
	dvC821_WriteToBuffer(B0_LVDSO1CT,		0x00,0);	//Output side LVDS1 control
	dvC821_WriteToBuffer(B0_LVDSO2CT,		0x01,0);

    //TODO :
    switch(ePanelId)
    {
        case ePANEL_ID_WUXGA_60HZ:
        case ePANEL_ID_1080P_60HZ:
	        dvC821_WriteToBuffer(B0_LVDSTXCT1,		0x09,0);	//###Output side LVDS macro control when clock freq. is 60~100 MHz
	        dvC821_WriteToBuffer(B0_LVDSTXCT2,		0x09,0);    //A70LV_Doulas_0002
            break;

        case ePANEL_ID_720P_60HZ:
	        dvC821_WriteToBuffer(B0_LVDSTXCT1,		0x08,0);	//###Output side LVDS macro control when clock freq. is 16~60 MHz
	        dvC821_WriteToBuffer(B0_LVDSTXCT2,		0x08,0);    //A70LV_Doulas_0002
            break;

        case ePANEL_ID_1080P_120HZ:     //A70LV_Doulas_0377  Modify
            if(dvC821_Input_3D_Format_Config_Get() ==  eINPUT_3D_TYPE_FRAME_SEQUENTIAL)    //A70LV_Doulas_0154 modify
            {
                dvC821_WriteToBuffer(B0_LVDSOSETUP,		0x04,0);    //A70LV_Doulas_0098
            }
            else
            {
                dvC821_WriteToBuffer(B0_LVDSOSETUP,		0x00,0);
            }
            dvC821_WriteToBuffer(B0_LVDSTXCT1,		0x0A,0);	//###Output side LVDS macro control when clock freq. is 100?140 MHz
            dvC821_WriteToBuffer(B0_LVDSTXCT2,		0x0A,0);
            break;

        case ePANEL_ID_WUXGA_120HZ:     //A70LV_Doulas_0377 Add
            if(dvC821_Input_3D_Format_Config_Get() ==  eINPUT_3D_TYPE_FRAME_SEQUENTIAL)
            {
                dvC821_WriteToBuffer(B0_LVDSOSETUP,		0x04,0);
            }
            else
            {
                dvC821_WriteToBuffer(B0_LVDSOSETUP,		0x00,0);
            }
            dvC821_WriteToBuffer(B0_LVDSTXCT1,		0x0B,0);	//###Output side LVDS macro control when clock freq. is Higher than 140 MHz
            dvC821_WriteToBuffer(B0_LVDSTXCT2,		0x0B,0);
            break;

        default:
	        dvC821_WriteToBuffer(B0_LVDSTXCT1,		0x09,0);	//###Output side LVDS macro control when clock freq. is 60~100 MHz
	        dvC821_WriteToBuffer(B0_LVDSTXCT2,		0x09,0);    //A70LV_Doulas_0002
            break;

    }

    dvC821_Buffer_Flush();
}

static void dvC821_ConfigIPMemory_2K(const eMCT eCH)
{
    UINT32 ulData = 0;
    if(eCH >= eMCT_LAST)
    {
        return;
    }

    if(eCH == eMCT_CH1)
    {
        dvC821_WriteToBuffer(B13_OMWICH1, DEF_MWI_2K, 0);
        dvC821_WriteToBuffer(B13_IMWICH1, DEF_MWI_2K, 0);

        //Setup De-interlacer
        dvC821_WriteToBuffer(B13_IPOSFLD0CH1, DEF_IPOSFLD0CH1_2K, 0);
        dvC821_WriteToBuffer(B13_IPOSFLD1CH1, DEF_IPOSFLD1CH1_2K, 0);
        dvC821_WriteToBuffer(B13_IPOSFLD2CH1, DEF_IPOSFLD2CH1_2K, 0);
        dvC821_WriteToBuffer(B13_IPOSFLD3CH1, DEF_IPOSFLD3CH1_2K, 0);
        dvC821_WriteToBuffer(B13_IPISFLD0CH1, DEF_IPISFLD0CH1_2K, 0);
        dvC821_WriteToBuffer(B13_IPISFLD1CH1, DEF_IPISFLD1CH1_2K, 0);
        dvC821_WriteToBuffer(B13_IPISFLD2CH1, DEF_IPISFLD2CH1_2K, 0);
        dvC821_WriteToBuffer(B13_IPISFLD3CH1, DEF_IPISFLD3CH1_2K, 0);
        //TODO
        ulData = ((0x07&DEF_MV_MWICH1_2K)<<5)|(DEF_IPMWICH1_2K&0x1f);
        dvC821_WriteToBuffer(B13_IPMWICH1, ulData , 0);//0x45, 1920 x (4/3)/1024x2 = 5
        dvC821_WriteToBuffer(B13_IPYOFFCH1, DEF_IPYOFFCH1_2K, 0);
        dvC821_WriteToBuffer(B13_MVFLDCH1, DEF_MVFLDCH1_2K, 0);
    }
    else if(eCH == eMCT_CH2)
    {
        dvC821_WriteToBuffer(B13_OMWICH1, DEF_MWI_2K, 13);
        dvC821_WriteToBuffer(B13_IMWICH1, DEF_MWI_2K, 13);

        dvC821_WriteToBuffer(B13_IPOSFLD0CH1, DEF_IPOSFLD0CH2_2K, 13);
        dvC821_WriteToBuffer(B13_IPOSFLD1CH1, DEF_IPOSFLD1CH2_2K, 13);
        dvC821_WriteToBuffer(B13_IPOSFLD2CH1, DEF_IPOSFLD2CH2_2K, 13);
        dvC821_WriteToBuffer(B13_IPOSFLD3CH1, DEF_IPOSFLD3CH2_2K, 13);
        dvC821_WriteToBuffer(B13_IPISFLD0CH1, DEF_IPISFLD0CH2_2K, 13);
        dvC821_WriteToBuffer(B13_IPISFLD1CH1, DEF_IPISFLD1CH2_2K, 13);
        dvC821_WriteToBuffer(B13_IPISFLD2CH1, DEF_IPISFLD2CH2_2K, 13);
        dvC821_WriteToBuffer(B13_IPISFLD3CH1, DEF_IPISFLD3CH2_2K, 13);

        ulData = ((0x07&DEF_MV_MWICH2_2K)<<5)|(DEF_IPMWICH2_2K&0x1f);
        dvC821_WriteToBuffer(B13_IPMWICH1, ulData, 13);
        dvC821_WriteToBuffer(B13_IPYOFFCH1, DEF_IPYOFFCH2_2K, 13);
        dvC821_WriteToBuffer(B13_MVFLDCH1, DEF_MVFLDCH2_2K, 13);
    }

    dvC821_Buffer_Flush();
}

static void dvC821_ConfigBasicMemory_2K(void)//dvC821_SetupMemory
{
    #if 0
    dvC821_Write(B0_DDR2CT2_0, 0xAA, 0);
    dvC821_Write(B0_DDR2CT2_1, 0x55, 0);
    dvC821_Write(B0_DDR2CT2_2, 0x55, 0);
    dvC821_Write(B0_DDR2CT2_3, 0x30, 0);
    dvC821_Write(B0_DDR2CT2_4, 0x00, 0);
    dvC821_Write(B0_DDR2CT2_5, 0x00, 0);
    dvC821_Write(B0_DLLCT, 0x9091, 0);

    dvC821_Write(B0_DDR2CT, 0x82, 0);

    MS_SLEEP(1);//1Ms
    dvC821_Write(BN_MEMCT, 0x09, 0);
    MS_SLEEP(1);
    dvC821_Write(B0_MPROTECT, 0x8D7F, 0);
    #endif

	dvC821_WriteToBuffer(B0_DDR3CT2_0,		0x22,0);	//DDR3 control 2
	dvC821_WriteToBuffer(B0_DDR3CT2_1,		0x44,0);
	dvC821_WriteToBuffer(B0_DDR3CT2_2,		0x22,0);
	dvC821_WriteToBuffer(B0_DDR3CT2_3,		0x77,0);
	dvC821_WriteToBuffer(B0_DDR3CT2_4,		0x07,0);
	dvC821_WriteToBuffer(B0_DDR3CT2_5,		0x30,0);

	dvC821_WriteToBuffer(B0_DDR3OCDDIP,		0x3f,0);	//DDR3 OCD P-ch driver impedance control
	dvC821_WriteToBuffer(B0_DDR3OCDDIN,		0x3f,0);	//DDR3 OCD N-ch driver impedance control

	dvC821_WriteToBuffer(B0_DDR3LVLCT,		0x00,0);
	dvC821_WriteToBuffer(B0_DDR3WRLVLPHCT,   0x101,0);
	dvC821_WriteToBuffer(B0_DDR3WRTMGCT,		0x00,0);
	dvC821_WriteToBuffer(B0_DDR3RDTMGCT,		0x00000,0);
	dvC821_WriteToBuffer(B0_DDR3RDTMGCT,		0x00000,0);
	dvC821_WriteToBuffer(B0_DDR3VREFCT,		0x09,0);
	dvC821_WriteToBuffer(B0_DDR3DLLCT,		0x0b,0);
	dvC821_WriteToBuffer(B0_DDR3ODTCT,		0x11,0);
	dvC821_WriteToBuffer(B0_DDR3ZQCT,		0x01,0);
    dvC821_Buffer_Flush();


	dvC821_Write(BN_DDR3CT,0x00,0);	//DDR3 control
	dvC821_Write(BN_MEMCT,0x00,0);	//Memory control

	dvC821_Write(BN_DDR3CT,0x84,0);	//DDR3 control 2G
	MS_SLEEP(1);
	dvC821_Write(BN_DDR3CT,0xd4,0);	//DDR3 control 2G
	MS_SLEEP(1);
	dvC821_Write(BN_MEMCT,0x69,0);//FPGA Cyclone3 setting //Memory control

}

static void dvC821_ConfigClock(const UINT8 ucPoRefDiv, const UINT8 ucPoFbDiv, const UINT8 ucIPPLLCT) //dvC821_SetupClock
{
    //TODO

    //Becaure channel 2~4 OSYCTCH will set to synchnorized with channel1 in the dvC821_SetOcycle()
    //Therefore, we only set enable pll in the ch1~ch4
    dvC821_Write(B0_POREFDIV, ucPoRefDiv, 0);
    dvC821_Write(B0_POFBDIV,  ucPoFbDiv, 0);     //75.0MHz/4*8=150MHz    //74.25MHz/1*2=148.5MHz
    if(m_sChannelInfo[eMCT_CH1].ePanelTimingId == ePANEL_ID_1080P_120HZ)     //A70LV_Doulas_0154 modify //A70LV_Doulas_0094
    {
        dvC821_Write(B0_POPLLCT,  0x08, 0);//0x0C, 0);     //A70LV_Doulas_0098
        dvC821_Write(B0_POPLLCT,  0x09, 0);//0x0D, 0);     //A70LV_Doulas_0098 //Enable PLL Control    //PLL Frquency Range From Higher than 160 MHz

        dvC821_Write(B0_POCLKCT,  0x01, 0);//0x00, 0);     //A70LV_Doulas_0098
    }
    else if(m_sChannelInfo[eMCT_CH1].ePanelTimingId == ePANEL_ID_WUXGA_120HZ)   //A70LV_Doulas_0377
    {
        dvC821_Write(B0_POPLLCT,  0x08, 0);
        dvC821_Write(B0_POPLLCT,  0x09, 0);      //Enable PLL Control    //PLL Frquency Range From Higher than 160 MHz

        dvC821_Write(B0_POCLKCT,  0x00, 0);
    }
    else
    {
        dvC821_Write(B0_POPLLCT,  0x08, 0);
        dvC821_Write(B0_POPLLCT,  0x09, 0);          //Enable PLL Control    //PLL Frquency Range From 80~160 MHz

        dvC821_Write(B0_POCLKCT,  0x00, 0);     //A70LV_Doulas_0002
    }
    dvC821_Write(B0_IPPLLCT,     ucIPPLLCT, 0);
    MS_SLEEP(10);//10Ms
    dvC821_Write(B0_IPREFDIV, ucPoRefDiv, 0);
    dvC821_Write(B0_IPFBDIV,  ucPoFbDiv, 0);

	//MS_SLEEP(10);//wait for 10ms
	//dvC821_Write(B0_IPREFDIV   ,ucPoRefDiv,0);
	//dvC821_Write(B0_IPFBDIV    ,ucPoFbDiv,0);
}

///////////////////////////////////////////////////////////////////////////////////
///@brief dvC821_GetPanelIndex : get panel table index from panel id
///@param ePANEL_ID ePanelId - panel id
///@param PUINT8 pucIndex - panel index pointer
///@return INT32 - return error code
///@author Roger Chen
///////////////////////////////////////////////////////////////////////////////////

static eC821_EXEC_CODE dvC821_GetPanelIndex(ePANEL_ID ePanelId, PUINT8 pucIndex)
{
    UINT8 ucIndex = 0;

    if(ePanelId < ePANEL_ID_LAST)
    {
        for(ucIndex = 0; ucIndex < m_ucPanelTblCount; ucIndex++)
        {
            if(m_sPanelTable[ucIndex].ePanelId == ePanelId)
            {
                *pucIndex = ucIndex;
                return eC821_EXEC_CODE_PASS;
            }
        }
    }
    else
    {
        return eC821_EXEC_CODE_PANEL_ID_NOT_FOUND;
    }

    return eC821_EXEC_CODE_PANEL_TABEL_INDEX_NOT_FOUND;
}

