void dvC821_BuildPicture_2K(eMCT eCH)
{
  //  UINT16 uiHzscl = 0;   //A70LV_Doulas_0008 remove
  //  UINT16 uiVzscl = 0;   //A70LV_Doulas_0008 remove
  //  sACTIVE_AREA sOact;   //A70LV_Doulas_0008 remove
  //  int		val;        //A70LV_Doulas_0008 remove

    if(!m_sChannelInfo[eCH].bInit)
    {
        return;
    }

    if(eCH == eMCT_CH1)
    {
        dvC821_SetInputPort_Output_Off(eCH);  //A35G2_CDS_Simon_0035
    }

    //LOG_MSG(db_DV_SCALER, "B30_WPBLKCT %x\n",(UINT8)dvC821_Read(B30_WPBLKCT  ,0));
    //halC821_InputSourceSetting(0);
    //dvC821_SetOverlay_2K(eCH, (BOOL)m_sChannelSetting[eMCT_CH1].cPIP_PBP_ON); //A70LV_Doulas_0108 remove //A70LV_Doulas_0007
    dvC821_SetInputMemoryBuffer_2K(eCH);      //A70LV_Doulas_0154 Add

    dvC821_Calc_Scaler_InputAndOutput_Window_2K(eCH);


    dvC821_Set_Sharpness(eCH);  //A70LV_Doulas_0003

    dvC821_Write(B0_RTCT, RTCT_STOP, 0);

    dvC821_Field_Interlock_Transfer_Control_Start();

	//if(!palDataPath_BKInput_Status())    //G100_Steven_0050     //H2 wait review
		dvC821_Auto_Fill_Screen_Init();

    dvC821_SetOverlay_2K(eCH, m_sChannelSetting[eMCT_CH1].cPIP_PBP_ON);   //ZU860_Doulas_0017//A70LV_Doulas_0108
    //dvC821_SetInput_2K(eCH);

    dvC821_WriteToBuffer(B8_IIMGCTCH1,0x00,0);
    dvC821_WriteToBuffer(B8_IIMGCTCH1,0x00,13);
    dvC821_Buffer_Flush();

	//dvC821_Set_Display_Window(ch,
	//	PM_IWIN_HST[ch],PM_IWIN_HW[ch],PM_IWIN_VST[ch],PM_IWIN_VW[ch],
	//	PM_OWIN_HST[ch],PM_OWIN_HW[ch],PM_OWIN_VST[ch],PM_OWIN_VW[ch]);
	dvC821_Set_ZoomShrink_2K(eCH);

    //dvC821_SetInputColor(eCH);      //A70LV_Doulas_0076 remove
    dvC821_Set_Color(eCH);
	//dvC821_set_datapath(ch);
	dvC821_Set_IP(eCH);

    dvC821_Set_flddly(eCH);
    dvC821_ConfigOutput_2K(eCH);

	dvC821_Set_Flip(eCH);

    //dvC821_SetInputPort_2K(eCH);     //A35G2_CDS_Simon_0005  move to bottom
    if(eCH == eMCT_CH2)    //A70LV_Doulas_0108 fixed CH1 抖動
    {
        dvC821_Set_Flip(eMCT_CH1);
    }

    dvC821_Write(B0_RTCT, RTCT_NORMAL, 0);       //0x4321CBA9

    //dvC821_WaitIntct(eCH, 0xF0);// wait POVS
    dvC821_WaitIntct(eCH, C821_INT_PI1VS);// wait POVS  //check output ports //A70LV_Larry_0001  //A35G2_CDS_Simon_0035
	dvC821_Field_Interlock_Transfer_Control_End();

    if(m_sChannelSetting[eMCT_CH1].cPIP_PBP_ON)  //A35G2_CDS_Simon_0035
    {
        if(eCH == eMCT_CH1)    //A35G2_CDS_Simon_0005 , to avoid show old FLD frame (garbage)
        {
            dvC821_WaitIntct(eCH, C821_INT_PI1VS);// wait PIVS   //A35G2_CDS_Simon_0035 (change to wait PIVS because input 24Hz timimg)
            dvC821_WaitIntct(eCH, C821_INT_PI1VS);// wait PIVS
            dvC821_WaitIntct(eCH, C821_INT_PI1VS);// wait PIVS
            dvC821_WaitIntct(eCH, C821_INT_PI1VS);// wait PIVS
        }
        else
        {
            dvC821_WaitIntct(eCH, C821_INT_PI2VS);// wait PIVS
            dvC821_WaitIntct(eCH, C821_INT_PI2VS);// wait PIVS
            dvC821_WaitIntct(eCH, C821_INT_PI2VS);// wait PIVS
            dvC821_WaitIntct(eCH, C821_INT_PI2VS);// wait PIVS
        }
    }

    dvC821_SetInputPort_2K(eCH);  //A35G2_CDS_Simon_0005

    //LOG_MSG(db_ALWAYS, "(func:%s, line:%d)CH= %d ,%08Xh\r\n", __FUNCTION__, __LINE__,eCH,dvC821_Read(B13_OSFLD1CH1,0)); //A70LV_Doulas_0108
    //halC821_InputSourceSetting(0);

}

void dvC821_BuildPicture_2K_ChangePIPLayout(eMCT eCH)    //A35G2_CDS_Simon_0001
{
    if(!m_sChannelInfo[eCH].bInit)
    {
        return;
    }

    dvC821_Calc_Scaler_InputAndOutput_Window_2K(eCH);
    dvC821_Write(B0_RTCT, RTCT_STOP, 0);

    dvC821_Field_Interlock_Transfer_Control_Start();

	//if(!palDataPath_BKInput_Status())    //G100_Steven_0050      //H2 wait review
		dvC821_Auto_Fill_Screen_Init();

    dvC821_SetOverlay_2K(eCH, m_sChannelSetting[eMCT_CH1].cPIP_PBP_ON);   //ZU860_Doulas_0017//A70LV_Doulas_0108
    dvC821_Set_ZoomShrink_2K(eCH);

    dvC821_Set_IP(eCH);

    dvC821_Set_Flip(eCH); //A35G2_CDS_Larry_0015

    if(eCH == eMCT_CH2)    // fixed CH1 抖動 //A35G2_CDS_Larry_0015
    {
        dvC821_Set_Flip(eMCT_CH1);
    }

    dvC821_Write(B0_RTCT, RTCT_NORMAL, 0);       //0x4321CBA9

    dvC821_WaitIntct(eCH, C821_INT_PO1VS);// wait POVS  //check output ports //A70LV_Larry_0001
	dvC821_Field_Interlock_Transfer_Control_End();

    if(eCH == eMCT_CH1)
    {
        dvC821_WaitIntct(eCH, C821_INT_PO1VS);// wait POVS
        dvC821_WaitIntct(eCH, C821_INT_PO1VS);// wait POVS
        dvC821_WaitIntct(eCH, C821_INT_PO1VS);// wait POVS
        dvC821_WaitIntct(eCH, C821_INT_PO1VS);// wait POVS
    }
    else
    {
        dvC821_WaitIntct(eCH, C821_INT_PO2VS);// wait POVS
        dvC821_WaitIntct(eCH, C821_INT_PO2VS);// wait POVS
        dvC821_WaitIntct(eCH, C821_INT_PO2VS);// wait POVS
        dvC821_WaitIntct(eCH, C821_INT_PO2VS);// wait POVS
    }

    dvC821_SetInputPort_2K(eCH);

}


eC821_EXEC_CODE dvC821_PSQ_EXE(ePSQ_STATE eState)
{
    static UINT8 ucState = 0x00;

    if(eState == ePSQ_STATE_RUN)
    {
        ucState |= 0x01;    //ENABLE
    }
    else if(eState == ePSQ_STATE_PAUSE)
    {
        ucState |= 0x08;    //PAUSE
    }
    else if(eState == ePSQ_STATE_RESTART)
    {
        ucState &= 0xF7;    //RESTART
    }
    else if(eState == ePSQ_STATE_STOP)
    {
        ucState = 0x00;    //STOP
    }

    dvC821_Write(BN_PSQCT , ucState, 0);

    return eC821_EXEC_CODE_PASS;

}
