void dvC821_RegDump(void)   //Owen_G100_0060
{
    UINT32 dwData = 0;
    UINT32 dwCount = 0;

    sICHIP_DUMP* m_pc821Reg = (sICHIP_DUMP*)malloc(sizeof(m_sICHIPC821_DUMP));

    if(m_pc821Reg == NULL)
    {
        LOG_MSG(db_ALWAYS,"\n%s(%d) malloc fail\n", __FUNCTION__ , __LINE__);
        return;
    }

    memcpy(m_pc821Reg, m_sICHIPC821_DUMP, sizeof(m_sICHIPC821_DUMP));

#if 0
    FILE *pRegFile = NULL;
    pRegFile = fopen("/usr/configs/scaler/system/c821_Reg", "rb");
    if(pRegFile != NULL)
    {
        if(fread(m_C821RegTbl, sizeof(m_C821RegTbl), 1, pRegFile) != 1)
        {
            LOG_MSG(db_ALWAYS, "Open c821 reg file failed !\r\n");
            fclose(pRegFile);
            return;
        }
        fclose(pRegFile);
    }
    else
    {
        LOG_MSG(db_ALWAYS, "Open c821 reg file failed !\r\n");
        return;
    }
#endif /* 0 */

    if(m_pc821Reg[dwCount].ulAddress == 0x12345678)
    {
        FILE *pDumpFile = NULL;
        char pString[128]={'\0'};
        LOG_MSG(db_ALWAYS, "C821 %s\r\n",  m_pc821Reg[dwCount].cReg);
        pDumpFile = fopen("/usr/configs/scaler/system/c821_dump", "wb+");
        if(pDumpFile == NULL)
        {
            LOG_MSG(db_ALWAYS, "Open c821 dump file failed !\r\n");
            free(m_pc821Reg);
            return;
        }

        dwCount++;

        while(1)
        {
            if(m_pc821Reg[dwCount].ulAddress == 0xFFFFFFFF)
            {
                LOG_MSG(db_ALWAYS, "C821 %s\r\n",  m_pc821Reg->cReg);
                fclose(pDumpFile);
                free(m_pc821Reg);
                return;
            }
            else
            {
                dwData = dvC821_Read(m_pc821Reg[dwCount].ulAddress, 0);

                memset(pString,'\0',128);

                switch(m_pc821Reg[dwCount].ulAddress & 0xFF)
                {
                    case 1:
                        LOG_MSG(db_ALWAYS, "C821%s %02xh\r\n",  m_pc821Reg[dwCount].cReg, dwData);
                        sprintf(pString,"C821%s %02xh\r\n",  m_pc821Reg[dwCount].cReg, dwData);
                        fwrite(pString, sizeof(char), strlen(pString), pDumpFile);
                        break;
                    case 2:
                        LOG_MSG(db_ALWAYS, "C821%s %04xh\r\n",  m_pc821Reg[dwCount].cReg, dwData);
                        sprintf(pString,"C821%s %04xh\r\n",  m_pc821Reg[dwCount].cReg, dwData);
                        fwrite(pString, sizeof(char), strlen(pString), pDumpFile);
                        break;
                    case 3:
                        LOG_MSG(db_ALWAYS, "C821%s %06xh\r\n",  m_pc821Reg[dwCount].cReg, dwData);
                        sprintf(pString,"C821%s %06xh\r\n",  m_pc821Reg[dwCount].cReg, dwData);
                        fwrite(pString, sizeof(char), strlen(pString), pDumpFile);
                        break;
                    case 4:
                        LOG_MSG(db_ALWAYS, "C821%s %08xh\r\n",  m_pc821Reg[dwCount].cReg, dwData);
                        sprintf(pString,"C821%s %08xh\r\n",  m_pc821Reg[dwCount].cReg, dwData);
                        fwrite(pString, sizeof(char), strlen(pString), pDumpFile);
                        break;
                    default:
                        break;
                 }

                 MS_SLEEP(3);
            }

            dwCount++;
        }

    }
    else
    {
        LOG_MSG(db_ALWAYS, "Read c821 reg file failed !\r\n");

        free(m_pc821Reg);
        return;
    }
}

