void dvC821_Freeze_Set(eMCT eCH,BOOL bFreezeEn)     //A70LV_Doulas_0004
{
    UINT8 ucRegOffset = 0;

    if(eCH >= eMCT_LAST)
    {
        return;
    }

    ucRegOffset = (eCH == eMCT_CH1) ? 0 : 13;
    m_sChannelSetting[eCH].cFREEZE = (UINT8)bFreezeEn;      //A70LV_Doulas_0030

    if(m_sChannelInfo[eCH].sInterlace_InputTimingInfo.eScanMode == eSCAN_MODE_INTERLACE)
    {
        if(m_sChannelSetting[eCH].cFREEZE == TRUE)      //A70LV_Doulas_0270 freeze issue
        {
            m_sChannelInfo[eCH].ucISYCT &= 0xF0;
            m_sChannelInfo[eCH].ucISYCT |= 0x02;
        }
        else
        {
            m_sChannelInfo[eCH].ucISYCT &= 0xF0;
        }
    }
    else
    {
        if(m_sChannelSetting[eCH].cFREEZE == TRUE)      //A70LV_Doulas_0270 freeze issue
        {
            m_sChannelInfo[eCH].ucISYCT &= 0xF0;
            m_sChannelInfo[eCH].ucISYCT |= 0x02;        //A70LV_Doulas_0286 Add
        }
        else
        {
            m_sChannelInfo[eCH].ucISYCT &= 0xF0;
            m_sChannelInfo[eCH].ucISYCT |= 0x01;
        }
    }

    if((m_sChannelInfo[eMCT_CH1].ePanelTimingId == ePANEL_ID_1080P_120HZ) ||
       (m_sChannelInfo[eMCT_CH1].ePanelTimingId == ePANEL_ID_WUXGA_120HZ))   //A70LV_Doulas_0377 Modify//A70LV_Doulas_0286 Add
    {
        if(eCH == eMCT_CH2)
        {
            m_sChannelInfo[eCH].ucISYCT &= 0xF0;
            m_sChannelInfo[eCH].ucISYCT |= 0x08;
        }
    }
  //  m_sChannelInfo[eCH].ucISYCT = (m_sChannelSetting[eCH].cFREEZE == TRUE) ? ((m_sChannelInfo[eCH].ucISYCT&0xf0)+0x02) : m_sChannelInfo[eCH].ucISYCT;  //A70LV_Doulas_0223 remove//A70LV_Doulas_0030 //A70LV_Doulas_0004 Add
    //m_sChannelInfo[eCH].ucISYCT = (m_sChannelSetting[eCH].cFREEZE == TRUE) ? (m_sChannelInfo[eCH].ucISYCT&0xf0) : m_sChannelInfo[eCH].ucISYCT;  //A70LV_Doulas_0270 remove//A70LV_Doulas_0223 modify freeze issue
	dvC821_Write(B8_ISYCTCH1, m_sChannelInfo[eCH].ucISYCT, ucRegOffset);		//Input port sync signal control

    if(ucNo_Signal_Config[eCH] == FALSE)  //A35G2_CDS_Simon_0017
    {
        dvC821_SetInputPort_2K(eCH);
    }

    if(m_sChannelSetting[eCH].cFREEZE == TRUE)  //A70LV_Doulas_0030
    {   //not auto fill back ground
	    dvC821_Channel1_Auto_Fill_Screen_Set(FALSE);
        dvC821_Channel2_Auto_Fill_Screen_Set(FALSE);
        dvC821_Warp_Auto_Fill_Screen_Set(FALSE);
    }
    else if(!bCapImgOutput)
    {
        dvC821_Auto_Fill_Screen_Init();
    }
}

