{
    return m_sChannelSetting[eCH].cFREEZE;      //A70LV_Doulas_0030
}

BOOL dvC821_Panel_Change_LVDS_Stop(void) //A70LV_Doulas_0005
{
    UINT32 g_RTCT;
    g_RTCT = RTCT_STOP;

    dvC821_Write(B0_RTCT,g_RTCT,0);

	dvC821_LVDS_Stop();
    MS_SLEEP(10);
    return eC821_EXEC_CODE_PASS;
}

BOOL dvC821_Panel_Change_Setting(eMCT eCH,const ePANEL_ID ePanelId) //A70LV_Doulas_0005
{
    UINT32 g_RTCT;
    UINT8 ucTblIndex = 0;
    eC821_EXEC_CODE eExecCode = eC821_EXEC_CODE_PASS;


    if((eExecCode = dvC821_GetPanelIndex(ePanelId, &ucTblIndex)) != eC821_EXEC_CODE_PASS)
    {
        LOG_MSG(db_DV_SCALER, "(func:%s, line:%d) C821 Get Panel Timing Index Fail = %d\n", __FUNCTION__, __LINE__, eExecCode);
        return eExecCode;
    }
    dvC821_GetCHOutputTiming_2K(eMCT_CH1, ucTblIndex);
    dvC821_GetCHOutputTiming_2K(eMCT_CH2, ucTblIndex);

    m_sChannelInfo[eMCT_CH1].ePanelTimingId = ePanelId;
    m_sChannelInfo[eMCT_CH1].sInputTimingInfo.eScanMode = eSCAN_MODE_NO_SIGNAL;
    m_sChannelInfo[eMCT_CH1].sInterlace_InputTimingInfo.eScanMode = eSCAN_MODE_NO_SIGNAL;
    m_sChannelInfo[eMCT_CH1].ucPanelIndex = ucTblIndex;
    m_sChannelInfo[eMCT_CH2].ePanelTimingId = ePanelId;
    m_sChannelInfo[eMCT_CH2].sInputTimingInfo.eScanMode = eSCAN_MODE_NO_SIGNAL;
    m_sChannelInfo[eMCT_CH2].sInterlace_InputTimingInfo.eScanMode = eSCAN_MODE_NO_SIGNAL;
    m_sChannelInfo[eMCT_CH2].ucPanelIndex = ucTblIndex;

    switch(dvC821_Input_3D_Format_Config_Get())        //A70LV_Doulas_0154
    {
        case eINPUT_3D_TYPE_FRAMEPACKING:
        case eINPUT_3D_TYPE_SIDEBYSIDE:
        case eINPUT_3D_TYPE_TOPANDBOTTOM:
            if((ePanelId == ePANEL_ID_1080P_120HZ) ||
               (ePanelId == ePANEL_ID_WUXGA_120HZ))   //A70LV_Doulas_0377 Modify//A70LV_Doulas_0318 modify
            {
                m_sChannelInfo[eMCT_CH2].ucInputPort = eMCT_CH1;
            }
            else
            {
                m_sChannelInfo[eMCT_CH2].ucInputPort = eMCT_CH2;
            }
            break;

        default:
            m_sChannelInfo[eMCT_CH2].ucInputPort = eMCT_CH2;
            break;
    }

    dvC821_ConfigClock(m_sPanelTable[ucTblIndex].sOutputTimingInfo.ucPoRefDiv,
                           m_sPanelTable[ucTblIndex].sOutputTimingInfo.ucPoFbDiv,
                           m_sChannelInfo[eCH].ucIPPLLCT);
    dvC821_ConfigBasicMemory_2K();
   // dvC821_SetMemAD_2K(eCH,&sOact);
   // dvC821_ConfigIPMemory_2K(eCH);
    dvC821_ConfigLVDS_2K(ePanelId);

    dvC821_SetInputMemoryBuffer_2K(eMCT_CH1);   //A70LV_Doulas_0154
    dvC821_SetInputMemoryBuffer_2K(eMCT_CH2);   //A70LV_Doulas_0154
    dvC821_ConfigOutput_2K(eMCT_CH1);
    dvC821_ConfigOutput_2K(eMCT_CH2);
    dvC821_Set_Flip(eMCT_CH2);          //A70LV_Doulas_0154
    dvC821_Set_Flip(eMCT_CH1);          //A70LV_Doulas_0154
    dvC821_SetInputPort_2K(eMCT_CH2);   //A70LV_Doulas_0154


    //dvC821_WAIP_init();


    g_RTCT = RTCT_NORMAL;
    dvC821_Write(B0_RTCT, g_RTCT , 0);

    return eExecCode;
}

BOOL dvC821_AutoPositionSetting(const eMCT eCH)   //A70LV_Doulas_0005
{
    //BOOL bAutoPositionEnable = FALSE;
    if(eCH >= eMCT_LAST)
    {
        return FALSE;
    }

    if(m_sChannelSetting[eCH].eInputSource != eCM_SOURCE_VGA)  //A70LV_Doulas_0013 Add
    {
        return FALSE;
    }

    if(bModeAdjustmentTableUse == TRUE)     //A70LV_Doulas_0195
    {
        return FALSE;
    }

    if((m_sChannelInfo[eMCT_CH1].ePanelTimingId == ePANEL_ID_1080P_120HZ) ||
       (m_sChannelInfo[eMCT_CH1].ePanelTimingId == ePANEL_ID_WUXGA_120HZ))   //A70LV_Doulas_0377 Modify//A70LV_Doulas_0195
    {
        return FALSE;
    }

    if(m_sChannelInfo[eCH].bAutoPosition == TRUE)          //A70LV_Doulas_0210 modify
    {
       // if((m_sChannelInfo[eCH].sInputTimingInfo.uiVActive == 288) &&
       //    (m_sChannelInfo[eCH].sInputTimingInfo.uiHActive == 720 || m_sChannelInfo[eCH].sInputTimingInfo.uiHActive == 1440) &&
       //    (m_sChannelInfo[eCH].sInterlace_InputTimingInfo.eScanMode == eSCAN_MODE_INTERLACE))
        if(m_sChannelSetting[eCH].eVGA_SYNC_TYPE == eVGA_SYNC_TYPE_SOG)
        {
            return FALSE;
        }
        else if(m_sChannelInfo[eCH].sInterlace_InputTimingInfo.eScanMode == eSCAN_MODE_INTERLACE)   //A70LV_Doulas_0244 Add,interlced not using auto position values
        {
            return FALSE;
        }
        else
        {
            return TRUE;
        }
    }
    else
    {
        return FALSE;
    }
}

UINT32 dvC821_GetAPL(const eMCT eCH,UINT8 *ucMax,UINT8 *ucMin)   //A70LV_Doulas_0215 modify//A70LV_Doulas_0007
{
    UINT32 ucAPL = 0;
    if(eCH >= eMCT_LAST)
    {
        return FALSE;
    }

    if(eCH == eMCT_CH1)
    {
        ucAPL = dvC821_Read(B35_IAPL0CH1, 0);
        *ucMax = dvC821_Read(B35_IMAXFILTRCH1, 0);
        *ucMin = dvC821_Read(B35_IMINFILTRCH1, 0);
        LOG_MSG(db_DV_SCALER, "(func:%s, line:%d) Phase(%02d)=(%x)(%d,%d)\r\n", __FUNCTION__, __LINE__,m_sChannelInfo[eCH].sAutoPhase.uiCurrentPhase,ucAPL,*ucMax,*ucMin);  //A70LV_Doulas_0116
    }
    else
    {
        ucAPL = dvC821_Read(B35_IAPL0CH2, 0);
        *ucMax = dvC821_Read(B35_IMAXFILTRCH2, 0);
        *ucMin = dvC821_Read(B35_IMINFILTRCH2, 0);
        LOG_MSG(db_DV_SCALER, "(func:%s, line:%d) Phase(%02d)=(%x)(%d,%d)\r\n", __FUNCTION__, __LINE__,m_sChannelInfo[eCH].sAutoPhase.uiCurrentPhase,ucAPL,*ucMax,*ucMin);  //A70LV_Doulas_0116
    }
    return ucAPL;
}

eC821_EXEC_CODE dvC821_AutoPhaseStart(const eMCT eCH)   //A70LV_Doulas_0007
{
    eC821_EXEC_CODE eExecCode = eC821_EXEC_CODE_PASS;

    if(dvC821_Input_3D_Format_Config_Get() == eINPUT_3D_TYPE_OFF)    //A70LV_Doulas_0154 modify
    {
        if(m_sChannelSetting[eCH].eInputSource == eCM_SOURCE_VGA)   //A70LV_Doulas_0013 modify
        {
            m_sChannelInfo[eCH].sAutoPhase.uiBestPAL = 0;
            m_sChannelInfo[eCH].sAutoPhase.uiBestPhase = 0;
            m_sChannelInfo[eCH].sAutoPhase.uiCurrentPhase = 0;
            m_sChannelInfo[eCH].sAutoPhase.ucBestMax = 0;       //A70LV_Doulas_0215
            m_sChannelInfo[eCH].sAutoPhase.ucBestMin = 0;       //A70LV_Doulas_0215
            dvC821_BuildPicture_2K(eCH);    //A70LV_Doulas_0116
        }
        else
            eExecCode = eC821_EXEC_CODE_FAIL;
    }
    else
    {
        eExecCode = eC821_EXEC_CODE_FAIL;
    }

    return eExecCode;
}

eC821_EXEC_CODE dvC821_AutoPhase(const eMCT eCH)    //A70LV_Doulas_0007
{
    eC821_EXEC_CODE eExecCode;
    UINT32 ucAPL = 0;
    UINT8  ucMax = 0;   //A70LV_Doulas_0215
    UINT8  ucMin = 0;   //A70LV_Doulas_0215

    if(m_sChannelInfo[eCH].sAutoPhase.uiCurrentPhase <= VGA_MAX_PHASE)
    {
        #if 1       //A70LV_Doulas_0215 modify auto phase algorithm
        ucAPL = dvC821_GetAPL(eCH,&ucMax,&ucMin);
        if(ucMax > m_sChannelInfo[eCH].sAutoPhase.ucBestMax)
        {
            m_sChannelInfo[eCH].sAutoPhase.ucBestMax = ucMax;
            m_sChannelInfo[eCH].sAutoPhase.ucBestMin = ucMin;
            m_sChannelInfo[eCH].sAutoPhase.uiBestPAL = ucAPL;
            m_sChannelInfo[eCH].sAutoPhase.uiBestPhase = m_sChannelInfo[eCH].sAutoPhase.uiCurrentPhase;
        }
        else if(ucMax == m_sChannelInfo[eCH].sAutoPhase.ucBestMax)
        {
            if(ucAPL > m_sChannelInfo[eCH].sAutoPhase.uiBestPAL )
            {
                m_sChannelInfo[eCH].sAutoPhase.ucBestMax = ucMax;
                m_sChannelInfo[eCH].sAutoPhase.ucBestMin = ucMin;
                m_sChannelInfo[eCH].sAutoPhase.uiBestPAL = ucAPL;
                m_sChannelInfo[eCH].sAutoPhase.uiBestPhase = m_sChannelInfo[eCH].sAutoPhase.uiCurrentPhase;
            }
        }
        #else
        ucAPL = dvC821_GetAPL(eCH,&ucMax,&ucMin);
        if(ucAPL > m_sChannelInfo[eCH].sAutoPhase.uiBestPAL )
        {
            m_sChannelInfo[eCH].sAutoPhase.uiBestPAL = ucAPL;
            m_sChannelInfo[eCH].sAutoPhase.uiBestPhase = m_sChannelInfo[eCH].sAutoPhase.uiCurrentPhase;
        }
        #endif
        m_sChannelInfo[eCH].sAutoPhase.uiCurrentPhase++;
        eExecCode = eC821_EXEC_CODE_CH_AUTO_PHASE;
    }
    else
    {
        eExecCode = eC821_EXEC_CODE_PASS;
    }

    return eExecCode;
}

