void dvC821_SetContrast(const eMCT eCH) //A70LV_Doulas_0011 modify
{
    UINT8 ucRegOffset = 0;
    UINT32 ulVal;

    if(eCH >= eMCT_LAST)
    {
        return;
    }

    if(m_sChannelSetting[eMCT_CH1].cPIP_PBP_ON == FALSE)
    {
        if((m_sChannelInfo[eMCT_CH1].ePanelTimingId == ePANEL_ID_1080P_120HZ) ||
           (m_sChannelInfo[eMCT_CH1].ePanelTimingId == ePANEL_ID_WUXGA_120HZ))   //A70LV_Doulas_0377 Modify//A70LV_Doulas_0155 modify
        {

        }
        else if(eCH == eMCT_CH2)
        {
            return ;
        }
    }

    ucRegOffset = (eCH == eMCT_CH1) ? 0 : 13;

	ulVal = ((int)( 512*(m_sChannelSetting[eCH].dContrast)));
	if (ulVal > 0x07FF)
    {       // Overflow limit
		ulVal = 0x07FF;
	}
	ulVal = ulVal & 0x07FF;


    dvC821_Write(B0_RTCT, RTCT_POVSSTOP, 0);   //0x4321FFFF

    dvC821_Write(B6_BGCTCH1,		0x01,ucRegOffset) ;
	dvC821_Write(B6_OGAIN1RCH1,ulVal  ,ucRegOffset);	//Output gain correction
	dvC821_Write(B6_OGAIN1GCH1,ulVal  ,ucRegOffset);
	dvC821_Write(B6_OGAIN1BCH1,ulVal  ,ucRegOffset);

    dvC821_Write(B0_RTCT, RTCT_NORMAL, 0);   //0x4321CBA9
}

void dvC821_Scale_Overscan(eOVER_SCAN_TYPE ucOverScan,PsINPUT_TIMING_INFO psScalerInput,PsOUTPUT_TIMING_INFO psScalerOutput) //A70LV_Doulas_0009
{
    UINT16 wOverscanPercentage, wPixels;

    switch(ucOverScan)
    {
        case eOVER_SCAN_CROP: //overscan - crop 3%
            //caculate input
            wOverscanPercentage = 3;
            wPixels = (UINT16)(((wOverscanPercentage) * psScalerInput->uiHActive) / 100);
            psScalerInput->uiHStart += wPixels;
            psScalerInput->uiHActive -=  (2 * wPixels);

            wPixels = (UINT16)(((wOverscanPercentage) * psScalerInput->uiVActive) / 100);
            psScalerInput->uiVStart += wPixels;
            psScalerInput->uiVActive -=  (2 * wPixels);

            //caculate output
            wOverscanPercentage = 3;
            wPixels = (UINT16)(((wOverscanPercentage) * psScalerOutput->uiHActive) / 100);
            psScalerOutput->uiHStart += wPixels;
            psScalerOutput->uiHActive -=  (2 * wPixels);

            wPixels = (UINT16)(((wOverscanPercentage) * psScalerOutput->uiVActive) / 100);
            psScalerOutput->uiVStart += wPixels;
            psScalerOutput->uiVActive -=  (2 * wPixels);
            break;

        case eOVER_SCAN_ZOOM://overscan - zoom
            //caculate input
            wOverscanPercentage = 3;
            wPixels = (UINT16)(((wOverscanPercentage) * psScalerInput->uiHActive) / 100);
            psScalerInput->uiHStart += wPixels;
            psScalerInput->uiHActive -=  (2 * wPixels);

            wPixels = (UINT16)(((wOverscanPercentage) * psScalerInput->uiVActive) / 100);
            psScalerInput->uiVStart += wPixels;
            psScalerInput->uiVActive -=  (2 * wPixels);

            break;

        case eOVER_SCAN_OFF:
        default:

            break;
    }

}

