void dvC821_Set_RGB_Gain(const eMCT eCH)    //A70LV_Doulas_0011
{
    UINT8 ucRegOffset = 0;
    UINT32 ulRedGain;
    UINT32 ulGreenGain;
    UINT32 ulBlueGain;

    if(eCH >= eMCT_LAST)
    {
        return;
    }

    if(m_sChannelSetting[eMCT_CH1].cPIP_PBP_ON == FALSE)
    {
        if((m_sChannelInfo[eMCT_CH1].ePanelTimingId == ePANEL_ID_1080P_120HZ) ||
           (m_sChannelInfo[eMCT_CH1].ePanelTimingId == ePANEL_ID_WUXGA_120HZ))   //A70LV_Doulas_0377 Modify//A70LV_Doulas_0155 modify
        {

        }
        else if(eCH == eMCT_CH2)
        {
            return ;
        }
    }

    ucRegOffset = (eCH == eMCT_CH1) ? 0 : 13;

	ulRedGain = ((int)( 512*(m_sChannelSetting[eCH].dRedGain)));
	if (ulRedGain > 0x07FF)
    {       // Overflow limit
		ulRedGain = 0x07FF;
	}
	ulRedGain = ulRedGain & 0x07FF;


	ulGreenGain = ((int)( 512*(m_sChannelSetting[eCH].dGreenGain)));
	if (ulGreenGain > 0x07FF)
    {       // Overflow limit
		ulGreenGain = 0x07FF;
	}
	ulGreenGain = ulGreenGain & 0x07FF;


	ulBlueGain = ((int)( 512*(m_sChannelSetting[eCH].dBlueGain)));
	if (ulBlueGain > 0x07FF)
    {       // Overflow limit
		ulBlueGain = 0x07FF;
	}
	ulBlueGain = ulBlueGain & 0x07FF;

    dvC821_Write(B0_RTCT, RTCT_POVSSTOP, 0);   //0x4321FFFF

    dvC821_Write(B6_BGCT2CH1,		0x01,ucRegOffset) ;
	dvC821_Write(B6_OGAIN2RCH1,ulRedGain  ,ucRegOffset);	//Output gain correction
	dvC821_Write(B6_OGAIN2GCH1,ulGreenGain  ,ucRegOffset);
	dvC821_Write(B6_OGAIN2BCH1,ulBlueGain  ,ucRegOffset);

    dvC821_Write(B0_RTCT, RTCT_NORMAL, 0);   //0x4321CBA9
}

void dvC821_Set_RGB_Offset(const eMCT eCH)    //A70LV_Doulas_00011
{
    UINT8 ucRegOffset = 0;

    if(eCH >= eMCT_LAST)
    {
        return;
    }

    if(m_sChannelSetting[eMCT_CH1].cPIP_PBP_ON == FALSE)
    {
        if((m_sChannelInfo[eMCT_CH1].ePanelTimingId == ePANEL_ID_1080P_120HZ) ||
           (m_sChannelInfo[eMCT_CH1].ePanelTimingId == ePANEL_ID_WUXGA_120HZ))   //A70LV_Doulas_0377 Modify//A70LV_Doulas_0155 modify
        {

        }
        else if(eCH == eMCT_CH2)
        {
            return ;
        }
    }

    ucRegOffset = (eCH == eMCT_CH1) ? 0 : 13;

    dvC821_Write(B0_RTCT, RTCT_POVSSTOP, 0);   //0x4321FFFF

    dvC821_Write(B6_BGCT2CH1,		0x01,ucRegOffset) ;
 	dvC821_Write(B6_OBIAS2RCH1,(m_sChannelSetting[eCH].iRedOffset)&0x0fff,ucRegOffset);	//Output bias correction
 	dvC821_Write(B6_OBIAS2GCH1,(m_sChannelSetting[eCH].iGreenOffset)&0x0fff,ucRegOffset);
 	dvC821_Write(B6_OBIAS2BCH1,(m_sChannelSetting[eCH].iBlueOffset)&0x0fff,ucRegOffset);

    dvC821_Write(B0_RTCT, RTCT_NORMAL, 0);   //0x4321CBA9
}

