void dvC821_TestPattern_Set(const eMCT eCH,UINT8 ucVal)     //A70LV_Doulas_0035
{
    m_sChannelSetting[eCH].cTestPattern = ucVal;
    switch(ucVal)
    {
        default:
        case eCM_TEST_PATTERN_OFF:
            dvC821_Set_Output_Fill_Color(FALSE,eFILL_COLOR_BLACK);
            dvC821_Set_Output_Test_Pattern(FALSE,0);
            break;

        case eCM_TEST_PATTERN_GRID:
            dvC821_Set_Output_Test_Pattern(TRUE,8);
            break;

        case eCM_TEST_PATTERN_WHITE:
            dvC821_Set_Output_Fill_Color(TRUE,eFILL_COLOR_WHITE);
            break;

        case eCM_TEST_PATTERN_BLACK:
            dvC821_Set_Output_Fill_Color(TRUE,eFILL_COLOR_BLACK);
            break;

        case eCM_TEST_PATTERN_CHECKERBOARD:
            dvC821_Set_Output_Test_Pattern(TRUE,5);
            break;

        case eCM_TEST_PATTERN_COLORBAR:
            dvC821_Set_Output_Test_Pattern(TRUE,1);
            break;

        case eCM_TEST_PATTERN_RED:
            dvC821_Set_Output_Fill_Color(TRUE,eFILL_COLOR_RED);
            break;

        case eCM_TEST_PATTERN_GREEN:
            dvC821_Set_Output_Fill_Color(TRUE,eFILL_COLOR_GREEN);
            break;

        case eCM_TEST_PATTERN_BLUE:
            dvC821_Set_Output_Fill_Color(TRUE,eFILL_COLOR_BLUE);
            break;

        case eCM_TEST_PATTERN_YELLOW:
            dvC821_Set_Output_Fill_Color(TRUE,eFILL_COLOR_YELLOW);
            break;

        case eCM_TEST_PATTERN_MAGENTA:
            dvC821_Set_Output_Fill_Color(TRUE,eFILL_COLOR_MAGENTA);
            break;

        case eCM_TEST_PATTERN_CYAN:
            dvC821_Set_Output_Fill_Color(TRUE,eFILL_COLOR_CYAN);
            break;

        case eCM_TEST_PATTERN_BORESIGHT:
            dvC821_Set_Output_Test_Pattern(TRUE,14);
            break;

        case eCM_TEST_PATTERN_FULL_SCREEN:
            dvC821_Set_Output_Test_Pattern(TRUE,3);     //A70LV_Doulas_0040 modify
            break;
    }
}

void dvC821_InputPixelClock_Get(const eMCT eCH,UINT8 *ucValue)   //A70LV_Doulas_0056
{
    char aucString[VERSION_STRING_MAX_LENGTH];
    DOUBLE dbVal;

    dbVal = m_sChannelInfo[eCH].sInputTimingInfo.dFrameRate *m_sChannelInfo[eCH].sInputTimingInfo.uiHTotal
           *m_sChannelInfo[eCH].sInputTimingInfo.uiVTotal / (DOUBLE)1000 ;

    switch(dvC821_Input_3D_Format_Get())  //A70LV_Doulas_0162 modify
    {
        case eINPUT_3D_TYPE_FRAME_SEQUENTIAL:
            dbVal = dbVal * 2;
            sprintf(aucString, "%d.%03dMHz\0",(UINT32)dbVal/1000,(UINT32)dbVal%1000);
            break;

        default:
            sprintf(aucString, "%d.%03dMHz\0",(UINT32)dbVal/1000,(UINT32)dbVal%1000);
            break;
    }
    memcpy(ucValue, aucString, strlen(aucString)+1);
}

void dvC821_InputResolution_Get(const eMCT eCH,UINT8 *ucValue)
{
    char aucString[VERSION_STRING_MAX_LENGTH];
    UINT16 uiH_Active;
    UINT16 uiV_Active;

    if(m_sChannelInfo[eCH].sInterlace_InputTimingInfo.eScanMode == eSCAN_MODE_INTERLACE)
    {
        if(m_sChannelInfo[eCH].sInputTimingInfo.uiHActive == 1440)
            uiH_Active = m_sChannelInfo[eCH].sInputTimingInfo.uiHActive/2;
        else
            uiH_Active = m_sChannelInfo[eCH].sInputTimingInfo.uiHActive;
        uiV_Active = m_sChannelInfo[eCH].sInputTimingInfo.uiVActive * 2;
    }
    else
    {
        switch(dvC821_Input_3D_Format_Get())  //A70LV_Doulas_0162 modify
        {
            case eINPUT_3D_TYPE_FRAME_SEQUENTIAL:
                uiH_Active = m_sChannelInfo[eCH].sInputTimingInfo.uiHActive * 2;
                uiV_Active = m_sChannelInfo[eCH].sInputTimingInfo.uiVActive;
                break;

            case eINPUT_3D_TYPE_FRAMEPACKING:
                uiH_Active = m_sChannelInfo[eCH].sInputTimingInfo.uiHActive;
                if(m_sChannelInfo[eCH].sInputTimingInfo.uiVActive > 2150)
                    uiV_Active = 1080;
                else
                    uiV_Active = 720;
                break;

            default:
                uiH_Active = m_sChannelInfo[eCH].sInputTimingInfo.uiHActive;
                uiV_Active = m_sChannelInfo[eCH].sInputTimingInfo.uiVActive;
                break;
        }
        //uiH_Active = m_sChannelInfo[eCH].sInputTimingInfo.uiHActive;
        //uiV_Active = m_sChannelInfo[eCH].sInputTimingInfo.uiVActive;
    }
    sprintf(aucString, "%d x %d\0",uiH_Active ,uiV_Active);
    memcpy(ucValue, aucString, strlen(aucString)+1);
}

void dvC821_InputHorzRefresh_Get(const eMCT eCH,UINT8 *ucValue)
{
    char aucString[VERSION_STRING_MAX_LENGTH];
    DOUBLE dbVal;

    dbVal = m_sChannelInfo[eCH].sInputTimingInfo.dFrameRate * (DOUBLE)m_sChannelInfo[eCH].sInputTimingInfo.uiVTotal;

    sprintf(aucString, "%d.%03dkHz\0",(UINT32)dbVal/1000,(UINT32)dbVal%1000);
    memcpy(ucValue, aucString, strlen(aucString)+1);
}

