void dvC821_ForcedSyncResetDisable_Set(void)     //A70LV_Doulas_0079
{
    dvC821_reg_set(B2_OHCYCLCH1, (m_sChannelInfo[eMCT_CH1].sOutputTimingInfo.uiHTotal - 2));
    dvC821_reg_set(B2_OVCYCLCH1, (m_sChannelInfo[eMCT_CH1].sOutputTimingInfo.uiVTotal - 2));
    dvC821_reg_set(B2_OHCYCLCH1, (m_sChannelInfo[eMCT_CH2].sOutputTimingInfo.uiHTotal - 2));    //A70LV_Doulas_0098
    dvC821_reg_set(B2_OVCYCLCH1, (m_sChannelInfo[eMCT_CH2].sOutputTimingInfo.uiVTotal - 2));    //A70LV_Doulas_0098

    dvC821_Write(B2_SYRDLYCH1, 0x00, 0);//Forced sync reset delay
    dvC821_Write(B2_OSYCT3CH1, 0x00, 0);     //A70LV_Doulas_0098 //Trigger forced sync reset in unit of HS.
    dvC821_Write(B2_FLDDLYCH1, 0x00, 0);

    if(m_sChannelSetting[eMCT_CH1].cPIP_PBP_ON == FALSE)    //ZU860_Doulas_0138 Add
    {
        dvC821_Write(B2_SYRDLYCH1, 0x00, 13);    //Forced sync reset delay
        dvC821_Write(B2_OSYCT3CH1, 0x00, 13);    //Trigger forced sync reset in unit of HS.
        dvC821_Write(B2_FLDDLYCH1, 0x00, 13);
    }
    #ifdef C821_WARPING_ENABLE  //A70LV_Doulas_0099 modify
    dvC821_Write(B30_OHCYCL,  m_sChannelInfo[eMCT_CH1].sOutputTimingInfo.uiHTotal - 2, 0);
    dvC821_Write(B30_OVCYCL,  m_sChannelInfo[eMCT_CH1].sOutputTimingInfo.uiVTotal - 2, 0);
    dvC821_Write(B30_SYRDLY, 0x00, 0);
    dvC821_Write(B30_FLDDLY, 0x50, 0);
    #endif

    uiForcedSyncResetH_Total = m_sChannelInfo[eMCT_CH1].sOutputTimingInfo.uiHTotal;
    uiForcedSyncResetV_Total = m_sChannelInfo[eMCT_CH1].sOutputTimingInfo.uiVTotal;

    bForcedSyncResetEnable = FALSE;
}

void dvC821_ForcedSyncResetDisable_Set2(UINT16 uiH_Toral,UINT16 uiV_Toral)     //ZU860_Doulas_0138
{
    dvC821_reg_set(B2_OHCYCLCH1, (uiH_Toral - 2));
    dvC821_reg_set(B2_OVCYCLCH1, (uiV_Toral - 2));
    dvC821_reg_set(B2_OHCYCLCH1, (uiH_Toral - 2));
    dvC821_reg_set(B2_OVCYCLCH1, (uiV_Toral - 2));
    dvC821_Write(B2_SYRDLYCH1, 0x00, 0);    //Forced sync reset delay
    dvC821_Write(B2_OSYCT3CH1, 0x00, 0);    //Trigger forced sync reset in unit of HS.
    dvC821_Write(B2_FLDDLYCH1, 0x00, 0);

    if(m_sChannelSetting[eMCT_CH1].cPIP_PBP_ON == FALSE)
    {
        dvC821_Write(B2_SYRDLYCH1, 0x00, 13);    //Forced sync reset delay
        dvC821_Write(B2_OSYCT3CH1, 0x00, 13);    //Trigger forced sync reset in unit of HS.
        dvC821_Write(B2_FLDDLYCH1, 0x00, 13);
    }
    #ifdef C821_WARPING_ENABLE
    dvC821_Write(B30_OHCYCL,  uiH_Toral - 2, 0);
    dvC821_Write(B30_OVCYCL,  uiV_Toral - 2, 0);
    dvC821_Write(B30_SYRDLY, 0x00, 0);
    dvC821_Write(B30_FLDDLY, 0x50, 0);
    #endif
    uiForcedSyncResetH_Total = uiH_Toral;
    uiForcedSyncResetV_Total = uiV_Toral;

    bForcedSyncResetEnable = FALSE;
}

