UINT8 dvC821_Input_3D_Format_Config_Get(void)      //A70LV_Doulas_0159
{
    UINT8 uc3D_Format;
    UINT8 uc3D_Enable;
    //LOG_MSG(db_ALWAYS, "dvC821_OSD_3D_Enable  = (%d,%d) \r\n",m_sChannelSetting[eMCT_CH1].eOSD_3D_Enable,ucInput3D_Format);  //A70LV_Doulas_0160

    if(m_sChannelSetting[eMCT_CH1].eOSD_3D_Mode)    //ZU860_Doulas_0049
    {
        uc3D_Enable =  m_sChannelSetting[eMCT_CH1].eOSD_3D_Enable;
    }
    else
    {
        uc3D_Enable =  eCM_3D_FORMAT_OFF;
    }

    if(m_sChannelSetting[eMCT_CH1].cPIP_PBP_ON)     //ZU860_Doulas_0104
    {
        uc3D_Enable =  eCM_3D_FORMAT_OFF;
    }

    switch(uc3D_Enable)  //ZU860_Doulas_0049 modify
    {
        case eCM_3D_FORMAT_AUTO:
            uc3D_Format = ucInput3D_Format;
            break;

        case eCM_3D_FORMAT_FRAME_PACKING:
            if(ucInput3D_Format == eINPUT_3D_TYPE_FRAME_SEQUENTIAL)
                uc3D_Format = ucInput3D_Format;
            else
                uc3D_Format = eINPUT_3D_TYPE_FRAMEPACKING;
            break;

        case eCM_3D_FORMAT_SIDE_BY_SIDE:
            if(ucInput3D_Format == eINPUT_3D_TYPE_FRAME_SEQUENTIAL)
                uc3D_Format = ucInput3D_Format;
            else
                uc3D_Format = eINPUT_3D_TYPE_SIDEBYSIDE;
            break;

        case eCM_3D_FORMAT_TOP_AND_BOTTOM:
            if(ucInput3D_Format == eINPUT_3D_TYPE_FRAME_SEQUENTIAL)
                uc3D_Format = ucInput3D_Format;
            else
                uc3D_Format = eINPUT_3D_TYPE_TOPANDBOTTOM;
            break;

        case eCM_3D_FORMAT_FRAME_SEQUENTIAL:
            if(ucInput3D_Format == eINPUT_3D_TYPE_FRAME_SEQUENTIAL)
                uc3D_Format = ucInput3D_Format;
            else
                uc3D_Format = eINPUT_3D_TYPE_OFF;
            break;

        default:
            if(ucInput3D_Format == eINPUT_3D_TYPE_FRAME_SEQUENTIAL)
                uc3D_Format = ucInput3D_Format;
            else
                uc3D_Format = eINPUT_3D_TYPE_OFF;
            break;
    }
    return uc3D_Format;
}

void dvC821_SetInputMemoryBuffer_2K(eMCT eCH)      //A70LV_Doulas_0154
{
    UINT32 ulISFLD[4];//4 Bank
    UINT8  ucRegOffset = 0;

    if(eCH >= eMCT_LAST)
    {
        return;
    }

    ucRegOffset = (eCH == eMCT_CH1) ? 0 : 13;

    if(eCH == eMCT_CH1)
    {
        switch(dvC821_Input_3D_Format_Config_Get())
        {
            case eINPUT_3D_TYPE_FRAMEPACKING:
                ulISFLD[0] = 0x0;
                ulISFLD[1] = 0x974000;
                ulISFLD[2] = 0x0;
                ulISFLD[3] = 0x974000;
                break;

            case eINPUT_3D_TYPE_SIDEBYSIDE:
                ulISFLD[0] = 0x0;
                ulISFLD[1] = 0x974000;
                ulISFLD[2] = 0x0;
                ulISFLD[3] = 0x974000;
                break;

            case eINPUT_3D_TYPE_TOPANDBOTTOM:
                ulISFLD[0] = 0x0;
                ulISFLD[1] = 0x974000;
                ulISFLD[2] = 0x0;
                ulISFLD[3] = 0x974000;
                break;

            default:
                ulISFLD[0] = DEF_ISFLD0CH1_2K;
                ulISFLD[1] = DEF_ISFLD1CH1_2K;
                ulISFLD[2] = DEF_ISFLD2CH1_2K;
                ulISFLD[3] = DEF_ISFLD3CH1_2K;
                break;
        }
    }
    else if(eCH == eMCT_CH2)
    {
        switch(dvC821_Input_3D_Format_Config_Get())
        {
            case eINPUT_3D_TYPE_FRAMEPACKING:
                ulISFLD[0] = 0x3997c00;
                ulISFLD[1] = 0x430bc00;
                ulISFLD[2] = 0x3997c00;
                ulISFLD[3] = 0x430bc00;
                break;

            case eINPUT_3D_TYPE_SIDEBYSIDE:
           //     ulISFLD[0] = 0x000f00;
           //     ulISFLD[1] = 0x974f00;
           //     ulISFLD[2] = 0x000f00;
           //     ulISFLD[3] = 0x974f00;
                //A70LV_Doulas_0185 modify
                ulISFLD[0] = 0x03997c00;
                ulISFLD[1] = 0x0430bc00;
                ulISFLD[2] = 0x03997c00;
                ulISFLD[3] = 0x0430bc00;
                break;

            case eINPUT_3D_TYPE_TOPANDBOTTOM:
                //ulISFLD[0] = 0x2d0000;
                //ulISFLD[1] = 0xc44000;
                //ulISFLD[2] = 0x2d0000;
                //ulISFLD[3] = 0xc44000;
                //A70LV_Doulas_0185 modify
                ulISFLD[0] = 0x03997c00;
                ulISFLD[1] = 0x0430bc00;
                ulISFLD[2] = 0x03997c00;
                ulISFLD[3] = 0x0430bc00;
                break;

            default:
                ulISFLD[0] = DEF_ISFLD0CH2_2K;
                ulISFLD[1] = DEF_ISFLD1CH2_2K;
                ulISFLD[2] = DEF_ISFLD2CH2_2K;
                ulISFLD[3] = DEF_ISFLD3CH2_2K;
                break;
        }
    }

    dvC821_WriteToBuffer(B13_ISFLD0CH1, ulISFLD[0], ucRegOffset);
    dvC821_WriteToBuffer(B13_ISFLD1CH1, ulISFLD[1], ucRegOffset);
    dvC821_WriteToBuffer(B13_ISFLD2CH1, ulISFLD[2], ucRegOffset);
    dvC821_WriteToBuffer(B13_ISFLD3CH1, ulISFLD[3], ucRegOffset);
    dvC821_Buffer_Flush();
}

