BOOL dvC821_Find_Mode_Adjustment_table(eMCT eCH,sMODE_TABLE *m_FindModeTable,UINT8 *ucModeTableID)    //A70LV_Doulas_0195
{
    BOOL bFindModeTable;
    UINT16 wLastId, wModeId, wBestModeId;
    UINT16 wFit, wBestFit;
    INT16  nDVTotal;
    INT32  nDHFreq;
    UINT32 ucHFreq;
    UINT16 uiVTotal;

    ucHFreq = (m_sChannelInfo[eCH].ulMclko_Freq / 2) / IMFH_MCLK_COUNT[eCH];
    uiVTotal = (UINT16)(IMFV_MCLK_COUNT[eCH] / IMFH_MCLK_COUNT[eCH]);

    wModeId = 0;
    wBestFit = 0xFFFF;
    wBestModeId = 0xFFFF;
    if(m_sChannelSetting[eCH].eVGA_SYNC_TYPE == eVGA_SYNC_TYPE_SOG)
    {
        wLastId = 20 - 1;
        *ucModeTableID = eMODE_TABLE_ID_INDEX_SOG;
    }
    else
    {
        if(dvC821_AutoImage_Get() == eAUTO_IMAGE_WIDE)
        {
            wLastId = 20 - 1;
            *ucModeTableID = eMODE_TABLE_ID_INDEX_PC_WIDE;
        }
        else
        {
            wLastId = 20 - 1;
            *ucModeTableID = eMODE_TABLE_ID_INDEX_PC_NORMAL;
        }
    }

    for(; wModeId <= wLastId; wModeId++)
    {
        if((m_sModeAdjustmentTimingTable.ucNewMA_Mode_Flag[wModeId] == 0xA5) &&
           (((*ucModeTableID == eMODE_TABLE_ID_INDEX_SOG)&&(m_sModeAdjustmentTimingTable.ucNewMA_Table_ID[wModeId] == eMODE_TABLE_ID_INDEX_SOG)) ||
            ((*ucModeTableID != eMODE_TABLE_ID_INDEX_SOG)&&(m_sModeAdjustmentTimingTable.ucNewMA_Table_ID[wModeId] != eMODE_TABLE_ID_INDEX_SOG))))  //A70LV_Doulas_0198 modify
        {

            // get absolute delta between table and measured horizontal freq
            nDHFreq = ((INT32)m_sModeAdjustmentTimingTable.uiNewMA_HPeriod[wModeId] * 10) - (INT32)ucHFreq;
            // get absolute delta between table and measured vertical line count
            nDVTotal = (INT16)m_sModeAdjustmentTimingTable.uiNewMA_VTotal[wModeId] - (INT16)uiVTotal;


            if(nDHFreq < 0)
            {
            nDHFreq = -nDHFreq;
            }

            if(nDVTotal < 0)
            {
            nDVTotal = -nDVTotal;
            }
            //LOG_MSG(db_DV_SCALER, "Find_Mode_table(%d)..0x%x,%d..\n",wModeId,nDHFreq,nDVTotal);

            if((nDVTotal <= VTOTAL_TOLERANCE) && (nDHFreq <= HFREQ_TOLERANCE))
            {
                wFit = (UINT16)(nDVTotal * 100) + (UINT16)nDHFreq;
                if(wFit < wBestFit)
                {
                    wBestModeId = wModeId;
                    wBestFit = wFit;
                }
            }
        }
    }

    if(wBestModeId != 0xFFFF )
    {
        m_FindModeTable->uiModeTableNum = m_sModeAdjustmentTimingTable.uiNewMA_Mode_ID[wBestModeId];
        *ucModeTableID = m_sModeAdjustmentTimingTable.ucNewMA_Table_ID[wBestModeId];

        m_FindModeTable->sInputTimingInfo.uiHFreq    = (UINT32)m_sModeAdjustmentTimingTable.uiNewMA_HPeriod[wBestModeId] * 10;
        m_FindModeTable->sInputTimingInfo.uiHTotal   = m_sModeAdjustmentTimingTable.uiNewMA_HTotal[wBestModeId];
        m_FindModeTable->sInputTimingInfo.uiVTotal   = m_sModeAdjustmentTimingTable.uiNewMA_VTotal[wBestModeId];
        m_FindModeTable->sInputTimingInfo.uiHActive  = m_sModeAdjustmentTimingTable.uiNewMA_HActive[wBestModeId];
        m_FindModeTable->sInputTimingInfo.uiVActive  = m_sModeAdjustmentTimingTable.uiNewMA_VActive[wBestModeId];
        m_FindModeTable->sInputTimingInfo.uiHStart   = m_sModeAdjustmentTimingTable.uiNewMA_HStart[wBestModeId];
        m_FindModeTable->sInputTimingInfo.uiVStart   = m_sModeAdjustmentTimingTable.uiNewMA_VStart[wBestModeId];

        if(*ucModeTableID == eMODE_TABLE_ID_INDEX_SOG)
        {
            m_FindModeTable->sInputTimingInfo.dFrameRate = m_sModetableTableSOG[m_sModeAdjustmentTimingTable.uiNewMA_Mode_ID[wBestModeId]].sInputTimingInfo.dFrameRate;
            m_FindModeTable->sInputTimingInfo.eScanMode  = m_sModetableTableSOG[m_sModeAdjustmentTimingTable.uiNewMA_Mode_ID[wBestModeId]].sInputTimingInfo.eScanMode;
        }
        else if(*ucModeTableID == eMODE_TABLE_ID_INDEX_PC_WIDE)     //A70LV_Doulas_0123 modify
        {
            m_FindModeTable->sInputTimingInfo.dFrameRate = m_sModetableTableWide[m_sModeAdjustmentTimingTable.uiNewMA_Mode_ID[wBestModeId]].sInputTimingInfo.dFrameRate;
            m_FindModeTable->sInputTimingInfo.eScanMode  = m_sModetableTableWide[m_sModeAdjustmentTimingTable.uiNewMA_Mode_ID[wBestModeId]].sInputTimingInfo.eScanMode;
        }
        else if(*ucModeTableID == eMODE_TABLE_ID_INDEX_PC_NORMAL)     //A70LV_Doulas_0123
        {
            m_FindModeTable->sInputTimingInfo.dFrameRate = m_sModetableTableNormal[m_sModeAdjustmentTimingTable.uiNewMA_Mode_ID[wBestModeId]].sInputTimingInfo.dFrameRate;
            m_FindModeTable->sInputTimingInfo.eScanMode  = m_sModetableTableNormal[m_sModeAdjustmentTimingTable.uiNewMA_Mode_ID[wBestModeId]].sInputTimingInfo.eScanMode;
        }

        bFindModeTable = TRUE;
        bModeAdjustmentTableUse = TRUE;
        LOG_MSG(db_DV_SCALER, "Find_Mode_Adjustment_table(%d) = %d,%d  \n",*ucModeTableID,wBestModeId,m_sModeAdjustmentTimingTable.uiNewMA_Mode_ID[wBestModeId]);
    }
    else
    {
        bFindModeTable = FALSE;
        bModeAdjustmentTableUse = FALSE;
    }

    return bFindModeTable;
}

UINT8 dvC821_Input3D_Timing_Get(const eMCT eCH)   //A70LV_Doulas_0196
{
    UINT8  uc3DTiming = e3D_Customer_Timing;

    switch(dvC821_Input_3D_Format_Config_Get())
    {
        case eINPUT_3D_TYPE_FRAMEPACKING:
            uc3DTiming = e3DFP;
            break;

        case eINPUT_3D_TYPE_SIDEBYSIDE:
            uc3DTiming = e3DSbS;
            break;

        case eINPUT_3D_TYPE_TOPANDBOTTOM:
            uc3DTiming = e3DTB;
            break;

        case eINPUT_3D_TYPE_FRAME_SEQUENTIAL:
            if(((m_sChannelInfo[eCH].sInputTimingInfo.uiHActive*2) == 1920) &&
               (m_sChannelInfo[eCH].sInputTimingInfo.uiVActive == 1080))
            {
                uc3DTiming = e3DFS_1080P_120;
            }
            else
            {
                uc3DTiming = e3DFS_Other_120;
            }
            break;

        default:
            if((m_sChannelInfo[eCH].sInputTimingInfo.uiHActive == 1920) &&
                (m_sChannelInfo[eCH].sInputTimingInfo.uiVActive == 1080) &&
                (m_sChannelInfo[eCH].sInterlace_InputTimingInfo.eScanMode == eSCAN_MODE_PROGRESSIVE))
            {
                if((m_sChannelInfo[eCH].sInputTimingInfo.dFrameRate > 49 ) &&
                   (m_sChannelInfo[eCH].sInputTimingInfo.dFrameRate < 51 ))
                {
                    uc3DTiming = e3DFS_1080P_50;
                }
                else if((m_sChannelInfo[eCH].sInputTimingInfo.dFrameRate > 59 ) &&
                        (m_sChannelInfo[eCH].sInputTimingInfo.dFrameRate < 61 ))
                {
                    uc3DTiming = e3DFS_1080P_60;
                }
                else
                {
                    uc3DTiming = e3D_Customer_Timing;
                }
            }
            else if ((m_sChannelInfo[eCH].sInputTimingInfo.uiHActive == 1920) &&
                     (m_sChannelInfo[eCH].sInputTimingInfo.uiVActive == 1200) &&
                     (m_sChannelInfo[eCH].sInterlace_InputTimingInfo.eScanMode == eSCAN_MODE_PROGRESSIVE))
            {
                if((m_sChannelInfo[eCH].sInputTimingInfo.dFrameRate > 59 ) &&
                   (m_sChannelInfo[eCH].sInputTimingInfo.dFrameRate < 61 ))
                {
                    uc3DTiming = e3DFS_WUXGA_60;
                }
                else
                {
                    uc3DTiming = e3D_Customer_Timing;
                }
            }
            else
            {
                uc3DTiming = e3D_Customer_Timing;
            }
            break;
    }

    return uc3DTiming;
}

