void dvC821_BuildScaler_2K(eMCT eCH)   //A70LV_Doulas_0284
{
    if(!m_sChannelInfo[eCH].bInit)
    {
        return;
    }

    dvC821_SetInputMemoryBuffer_2K(eCH);

    dvC821_Calc_Scaler_InputAndOutput_Window_2K(eCH);


    dvC821_Set_Sharpness(eCH);  //A70LV_Doulas_0003

    dvC821_Write(B0_RTCT, RTCT_STOP, 0);

    dvC821_Field_Interlock_Transfer_Control_Start();
    dvC821_Auto_Fill_Screen_Init();

    dvC821_SetOverlay_2K(eCH, m_sChannelSetting[eMCT_CH1].cPIP_PBP_ON);   //ZU860_Doulas_0017

    dvC821_Write(B8_IIMGCTCH1,0x00,0);
    dvC821_Write(B8_IIMGCTCH1,0x00,13);

	dvC821_Set_ZoomShrink_2K(eCH);

    //dvC821_Set_Color(eCH);

	dvC821_Set_IP(eCH);

    //dvC821_Set_flddly(eCH);
    dvC821_ConfigOutput_2K(eCH);

	//dvC821_Set_Flip(eCH);   //G100_Simon_0076, move to bottom

    dvC821_SetInputPort_2K(eCH);
    if(eCH == eMCT_CH2)    // fixed CH1 抖動
    {
        dvC821_Set_Flip(eMCT_CH1);
    }

    dvC821_Write(B0_RTCT, RTCT_NORMAL, 0);       //0x4321CBA9

    dvC821_WaitIntct(eCH, C821_INT_PO1VS);// wait POVS  //check output ports //A70LV_Larry_0001
	dvC821_Field_Interlock_Transfer_Control_End();

    MS_SLEEP(20);          //G100_Simon_0076   //avoid image flicker
	dvC821_Set_Flip(eCH);  //G100_Simon_0076

    //LOG_MSG(db_ALWAYS, "(func:%s, line:%d)CH= %d ,%08Xh\r\n", __FUNCTION__, __LINE__,eCH,dvC821_Read(B13_OSFLD1CH1,0)); //A70LV_Doulas_0108
}

void dvC821_Scale_EdgeMask(UINT8 ucEdgeMask,PsINPUT_TIMING_INFO psScalerInput,PsOUTPUT_TIMING_INFO psScalerOutput)      //ZU860_Doulas_0004
{
    UINT16 wOverscanPercentage, wPixels;

    //caculate input
    wOverscanPercentage = ucEdgeMask;
    wPixels = (UINT16)(((wOverscanPercentage) * psScalerInput->uiHActive) / 100);
    psScalerInput->uiHStart += wPixels;
    psScalerInput->uiHActive -=  (2 * wPixels);

    wPixels = (UINT16)(((wOverscanPercentage) * psScalerInput->uiVActive) / 100);
    psScalerInput->uiVStart += wPixels;
    psScalerInput->uiVActive -=  (2 * wPixels);

    //caculate output
    wOverscanPercentage = ucEdgeMask;
    wPixels = (UINT16)(((wOverscanPercentage) * psScalerOutput->uiHActive) / 100);
    psScalerOutput->uiHStart += wPixels;
    psScalerOutput->uiHActive -=  (2 * wPixels);

    wPixels = (UINT16)(((wOverscanPercentage) * psScalerOutput->uiVActive) / 100);
    psScalerOutput->uiVStart += wPixels;
    psScalerOutput->uiVActive -=  (2 * wPixels);

}

