void dvC821_SetInputPort_Output_Off(const eMCT eCH)     //ZU860_Doulas_0124
{
    if(eCH >= eMCT_LAST)
    {
        return;
    }

    if(!m_sChannelInfo[eCH].bInit)
    {
        return;
    }

    m_sChannelInfo[eCH].ucMCT &= 0xFE ;    //A35G2_CDS_Simon_0005

    //LOG_MSG(db_APP_DATAPATH, "<10-%d> %d\n", eCH, m_sChannelInfo[eCH].ucMCT );

    switch(eCH)
    {
        case eMCT_CH1:
            dvC821_Write(BN_MCT1,  (m_sChannelInfo[eCH].ucMCT), 0);
            break;

        case eMCT_CH2:
            dvC821_Write(BN_MCT2,  (m_sChannelInfo[eCH].ucMCT), 0);
            break;
    }
}

