BOOL dvC821_SpecialTiming_Check_1280_960_85(const eMCT eCH, UINT32 *ulValue)
{
	if((m_sChannelInfo[eCH].sInputTimingInfo.uiHActive==1280) &&
		(m_sChannelInfo[eCH].sInputTimingInfo.uiVActive == 960) &&
		(m_sChannelInfo[eCH].sInputTimingInfo.dFrameRate >= 82.5 && m_sChannelInfo[eCH].sInputTimingInfo.dFrameRate <= 87.5))
	{
         *ulValue = (((*ulValue + (2 * IMFH_MCLK_TOLERANCE)) & 0x09FF) | 0x0900) - (2 * IMFH_MCLK_TOLERANCE);
         //LOG_MSG(db_DV_SCALER, "(dvC821_SpecialTiming_Check_1280_960_85) : %x\r\n",*ulValue);
		 return TRUE;

	}
	else
	{
		 return FALSE;
	}
}

