void dvC821_InputPort_Set(const eMCT eCH,UINT8 ucInputSource)     //R70G2_Doulas_0002
{
	//PIP on/off port的定義有不同
	if(m_sChannelSetting[eMCT_CH1].cPIP_PBP_ON)
	{
		switch(m_sChannelSetting[eMCT_CH1].eInputSource)	//main
		{
			case eCM_SOURCE_HDMI1: //2.0
				m_sChannelInfo[eMCT_CH1].ucInputPort = eINPUT_PORT2;
				m_sChannelInfo[eMCT_CH2].ucInputPort = eINPUT_PORT1;
     			break;

			case eCM_SOURCE_HDMI2: //1.4a
				switch(m_sChannelSetting[eMCT_CH2].eInputSource)		//sub
				{
					default:
					case eCM_SOURCE_HDMI1: //2.0
						m_sChannelInfo[eMCT_CH1].ucInputPort = eINPUT_PORT1;
						m_sChannelInfo[eMCT_CH2].ucInputPort = eINPUT_PORT2;
						break;

					case eCM_SOURCE_HDBASET:
						m_sChannelInfo[eMCT_CH1].ucInputPort = eINPUT_PORT2;
						m_sChannelInfo[eMCT_CH2].ucInputPort = eINPUT_PORT1;
						break;

					case eCM_SOURCE_VGA:
						m_sChannelInfo[eMCT_CH1].ucInputPort = eINPUT_PORT2;
						m_sChannelInfo[eMCT_CH2].ucInputPort = eINPUT_PORT1;
						break;
				}
     			break;

			case eCM_SOURCE_HDBASET:
				switch(m_sChannelSetting[eMCT_CH2].eInputSource)
				{
					default:
					case eCM_SOURCE_HDMI1: //2.0
						m_sChannelInfo[eMCT_CH1].ucInputPort = eINPUT_PORT1;
						m_sChannelInfo[eMCT_CH2].ucInputPort = eINPUT_PORT2;
						break;

					case eCM_SOURCE_HDMI2: //1.4a
						m_sChannelInfo[eMCT_CH1].ucInputPort = eINPUT_PORT1;
						m_sChannelInfo[eMCT_CH2].ucInputPort = eINPUT_PORT2;
						break;

					case eCM_SOURCE_VGA:
						m_sChannelInfo[eMCT_CH1].ucInputPort = eINPUT_PORT2;
						m_sChannelInfo[eMCT_CH2].ucInputPort = eINPUT_PORT1;
						break;
				}
     			break;

			case eCM_SOURCE_VGA:
				m_sChannelInfo[eMCT_CH1].ucInputPort = eINPUT_PORT1;
				m_sChannelInfo[eMCT_CH2].ucInputPort = eINPUT_PORT2;
				break;

			default:
				m_sChannelInfo[eMCT_CH1].ucInputPort = eINPUT_PORT2;
				m_sChannelInfo[eMCT_CH2].ucInputPort = eINPUT_PORT1;
				break;
		}
		dvC821_SetInputPort_2K(eMCT_CH1);
		dvC821_SetInputPort_2K(eMCT_CH2);
		#if 0
		if(eCH == eMCT_CH1)
		{
			switch(ucInputSource)
			{
     			case eCM_SOURCE_VGA:
				case eCM_SOURCE_HDMI2: //1.4a
				case eCM_SOURCE_HDBASET:
					m_sChannelInfo[eCH].ucInputPort = eINPUT_PORT1;
     				break;

				case eCM_SOURCE_HDMI1: //2.0
					m_sChannelInfo[eCH].ucInputPort = eINPUT_PORT2;
     				break;

     			default:
					m_sChannelInfo[eCH].ucInputPort = eINPUT_PORT2;
     				break;
			}
			dvC821_SetInputPort_2K(eCH);
		}
		else
		{
			switch(ucInputSource)
			{
     			case eCM_SOURCE_VGA:
				case eCM_SOURCE_HDMI2: //1.4a
				case eCM_SOURCE_HDBASET:
					m_sChannelInfo[eCH].ucInputPort = eINPUT_PORT1;
     				break;

				case eCM_SOURCE_HDMI1: //2.0
					m_sChannelInfo[eCH].ucInputPort = eINPUT_PORT2;
     				break;

     			default:
					m_sChannelInfo[eCH].ucInputPort = eINPUT_PORT2;
     				break;
			}
			dvC821_SetInputPort_2K(eCH);
		}
		#endif
	}
	else
	{
		switch(ucInputSource)
		{
			case eCM_SOURCE_VGA:
				m_sChannelInfo[eCH].ucInputPort = eINPUT_PORT1;
				break;

			default:
				m_sChannelInfo[eCH].ucInputPort = eINPUT_PORT2;
				break;
		}

		if((m_sChannelInfo[eMCT_CH1].ePanelTimingId == ePANEL_ID_WXGA_120HZ)	&&
		   (eCH == eMCT_CH2))		//R70G2_Doulas_0004
		{
			m_sChannelInfo[eCH].ucInputPort = m_sChannelInfo[eMCT_CH1].ucInputPort;
		}
		dvC821_SetInputPort_2K(eCH);
	}
}

void dvC821_InputPort_Show(void)     //R70G2_Doulas_0002
{
	LOG_MSG(db_ALWAYS, "Main = (%d,%d)\r\n",m_sChannelSetting[eMCT_CH1].eInputSource,m_sChannelInfo[eMCT_CH1].ucInputPort);
	LOG_MSG(db_ALWAYS, "Sub  = (%d,%d)\r\n",m_sChannelSetting[eMCT_CH2].eInputSource,m_sChannelInfo[eMCT_CH2].ucInputPort);
}



void dvC821_PowerNormalDone(BOOL bDone) //R70G2_Donview_Sammy_0040
{
    bPowerNormalDone = bDone;
}

UINT32 dvC821_CurrentBankGet(void)
{
    sPROCESS_MUTEX_DATA *sProcessMutexData = (sPROCESS_MUTEX_DATA *)SharedMem_GetMapPtr(eSB_PROCESS_MUTEX_DATA);

    return sProcessMutexData->Scaler_CurrentBank;
}

void dvC821_CurrentBankSet(UINT32 CurrentBank)
{
    sPROCESS_MUTEX_DATA *sProcessMutexData = (sPROCESS_MUTEX_DATA *)SharedMem_GetMapPtr(eSB_PROCESS_MUTEX_DATA);

    sProcessMutexData->Scaler_CurrentBank = (UINT32)CurrentBank;
}

